module barrel_shifter (
    input [7:0] in,
    input [2:0] ctrl,
    output reg [7:0] out
);

    wire [7:0] temp1, temp2, temp3;

    assign temp1 = (ctrl[2]) ? {in[3:0], in[7:4]} : in;
    assign temp2 = (ctrl[1]) ? {temp1[1:0], temp1[7:2]} : temp1;
    assign temp3 = (ctrl[0]) ? {temp2[0], temp2[7:1]} : temp2;

    assign out = temp3;

endmodule

module mux2X1( in0,in1,sel,out);
input in0,in1;
input sel;
output out;
assign out=(sel)?in1:in0;
endmodule
